		projectId,
		taskId,
		runnerId,
		executionId,
		epoch,
		sha = null,
		branch = null,
		posture = null,
	}) {
		let outcome;
		try {
			outcome = claimStore.complete(taskId, executionId, epoch);
		} catch (err) {
			this.counters.staleRejected += 1;
			throw err;
		}
		if (outcome.duplicate) {
			this.counters.completionDuplicates += 1;
			return { accepted: true, duplicate: true };
		}
		this.counters.completions += 1;
		const task = taskStore.getTask(projectId, taskId);
		const project = projectStore?.getProject?.(projectId);

		let shaState = "absent";
		if (sha && project?.cwd && !project?.hasUpstreamRepo) {
			try {
				// cat-file -e verifies the object exists; rev-parse alone
				// would echo back any 40-hex string without checking.
				await git(project.cwd, ["cat-file", "-e", `${sha}^{commit}`]);
				shaState = "present";
			} catch {
				shaState = "unverifiable";
				this.counters.unverifiedSha += 1;
			}
		} else if (sha) {
			shaState = "unverified-remote";
			this.counters.unverifiedSha += 1;
			// Deferred verification (Step 3): the backend cannot fetch the
			// remote (D2), so the reported SHA stays pending until a Runner
			// with a fresh fetch confirms it via noteRemoteVerification
			// (POST /tasks/:id/verify-sha). Visible per task, not just as a
			// monitor counter.
			if (task && branch) {
				task.pendingPushVerification = {
					sha,
					branch,
					verified: false,
					reportedAt: new Date().toISOString(),
					reportedBy: runnerId,
				};
			}
		}

		const reportedStage = this.lastStage.get(executionId) ?? null;
		const currentStage = task?.currentStageId ?? null;
		const terminal = ["complete", "failed"].includes(
			String(task?.status).toLowerCase(),
		);
		if ((reportedStage && currentStage && reportedStage !== currentStage) || terminal) {
			this.counters.divergences += 1;
			task?.history?.push({
				timestamp: new Date().toISOString(),
				action: `Reconciler: execution ${executionId} reported stage ${reportedStage ?? "?"} but task is at stage ${currentStage ?? "?"} (status ${task?.status}) — report kept, divergence counted.`,
			});
		}

		const postureBits = [
			runnerId && `runner ${runnerId}`,
			`epoch ${epoch}`,
			sha && `sha ${sha} (${shaState})`,
			branch && `branch ${branch}`,
			posture && `posture ${posture}`,
		]
			.filter(Boolean)
			.join(", ");
		task?.history?.push({
			timestamp: new Date().toISOString(),
			action: `Runner completed execution ${executionId} (${postureBits}). Lease released.`,
		});
		// G7: a finished stage breaks the death loop — the next stage (or
		// a later retry of this one after real progress) counts from zero.
		if (task) {
			delete task.runnerInterruptCount;
			delete task.runnerInterruptStage;
		}
		this.lastStage.delete(executionId);
		this.logNextSeq.delete(executionId);
		this.stagePrompt.delete(executionId);
		this.stageServing.delete(executionId);
		return { accepted: true, duplicate: false, shaState, reportedStage };
	}

	/***
	 * MARK: noteRemoteVerification
	 * @description Confirms (or refutes) a previously reported push SHA
	 *   against a Runner's fresh fetch of the remote (Step 3 deferred
	 *   verification). Fenced by the task-claim lease exactly like progress
	 *   and logs: a stale execution's confirmation is rejected, never
	 *   recorded. Sets `task.pendingPushVerification.verified` and counts
	 *   `verifiedSha`; a refuted SHA leaves `verified: false` with the
	 *   refuting Runner named, so the task visibly needs a re-push.
	 * @example ledger.noteRemoteVerification({ claimStore, taskStore, projectId: 'p', taskId: 't', runnerId: 'r', executionId: 'e', epoch: 1, sha: 'abc', present: true }) => { verified: true }
	 ***/
	noteRemoteVerification({
		claimStore,
		taskStore,
		projectId,
		taskId,
		runnerId,
		executionId,
		epoch,
		sha,
		present,
	}) {
		const hold = this._holdOrThrow(claimStore, taskId, executionId, epoch);
		if (hold.runnerId !== runnerId) {
			this.counters.staleRejected += 1;
			throw ExecutionLedger._stale(taskId, "lease belongs to another Runner");
		}
		if (!sha || typeof sha !== "string") {
			const err = new Error("verify-sha requires a sha.");
			err.statusCode = 400;
			err.code = "INVALID_VERIFY_ARGS";
			throw err;
		}
		const task = taskStore.getTask(projectId, taskId);
		const verified = present !== false;
		if (task) {
			task.pendingPushVerification = {
				...(task.pendingPushVerification || {}),
				sha,
				verified,
				verifiedAt: new Date().toISOString(),
				verifiedBy: runnerId,
			};
			task?.history?.push({
				timestamp: new Date().toISOString(),
				action: verified
					? `Runner ${runnerId} verified push SHA ${sha.slice(0, 7)} against the remote.`
					: `Runner ${runnerId} could NOT find push SHA ${sha.slice(0, 7)} on the remote — task needs a re-push.`,
			});
		}
		if (verified) this.counters.verifiedSha += 1;
		else this.counters.unverifiedSha += 1;
		return { verified };
	}

	interruptExecution({
		claimStore,
		taskStore,
		projectId,
		taskId,
		runnerId,
		executionId = null,
		reason = null,
	}) {
		const hold = claimStore.describe(taskId);
		if (
			hold &&
			executionId &&
			(executionId !== hold.executionId || runnerId !== hold.runnerId)
		) {
			this.counters.staleRejected += 1;
			throw ExecutionLedger._stale(taskId, "not the lease holder");
		}
		const task = taskStore.getTask(projectId, taskId);
		if (["complete", "failed"].includes(String(task?.status).toLowerCase())) {
			const err = new Error(`Task ${taskId} is already terminal.`);
			err.statusCode = 409;
			err.code = "NOTHING_TO_INTERRUPT";
			throw err;
		}
		claimStore.invalidate(taskId);
		this.counters.interrupts += 1;
		// G7: consecutive interrupts per task+stage. A stage change (or a
		// successful completion, which clears both fields) restarts the
		// count — only a Runner dying repeatedly on the SAME stage trips
		// the bound.
		const stageId = task?.currentStageId ?? null;
		const prevStage = task?.runnerInterruptStage ?? null;
		const prevCount = Number.isInteger(task?.runnerInterruptCount) ? task.runnerInterruptCount : 0;
		const interruptCount = prevStage === stageId ? prevCount + 1 : 1;
		const escalated = interruptCount >= MAX_RUNNER_INTERRUPTS;
		if (task) {
			task.runnerInterruptStage = stageId;
			task.runnerInterruptCount = interruptCount;
			task.status = "interrupted";
			const cleanReason =
				typeof reason === "string" && reason.trim() ? reason.trim().slice(0, 500) : "";
			task?.history?.push({
				timestamp: new Date().toISOString(),
				action: `Runner ${runnerId} interrupted execution ${executionId ?? hold?.executionId ?? "?"} — lease dropped, re-queues as interrupted.${cleanReason ? ` Reason: ${cleanReason}` : ""}`,
			});
			if (escalated) {
				this.counters.interruptEscalations += 1;
				task?.history?.push({
					timestamp: new Date().toISOString(),
					action: `Runner deaths escalated: ${interruptCount} consecutive interrupts on stage ${stageId ?? "?"} (bound ${MAX_RUNNER_INTERRUPTS}) — needs operator attention, auto re-queue continues.`,
				});
			}
		}
		for (const id of [hold?.executionId, executionId]) {
			if (id) {
				this.lastStage.delete(id);
				this.logNextSeq.delete(id);
				this.stagePrompt.delete(id);
				this.stageServing.delete(id);
			}
		}
		return { interrupted: true, interruptCount, escalated };
	}

	/***
	 * MARK: stageFor
	 * @description Current stage reported by a live execution (progress
	 *   `started`/`finished` events). Null when unknown or finished —
	 *   per-runner monitor widgets join this to the claim hold.
	 * @example ledger.stageFor('exec-1') => 'stage-a'
	 * @param {string} executionId - Lease execution id.
	 * @returns {string|null} Last reported stage id.
	 ***/
	stageFor(executionId) {
		return this.lastStage.get(executionId) ?? null;
	}

	/***
	 * MARK: promptFor
	 * @description Exact stage prompt a live execution reported at start
	 *   (`prompted` progress event). Null when unreported or finished —
	 *   per-runner monitor widgets render the with-prompt card from this.
	 * @example ledger.promptFor('exec-1') => '# Task\n...'
	 * @param {string} executionId - Lease execution id.
	 * @returns {string|null} Reported stage prompt.
	 ***/
	promptFor(executionId) {
		return this.stagePrompt.get(executionId) ?? null;
	}

	/***
	 * MARK: servingFor
	 * @description Serving harness/model a live execution reported at start
	 *   (`prompted` progress event). Null when unreported or finished —
	 *   per-runner monitor widgets show these pills instead of the fleet
	 *   advertised capabilities.
	 * @example ledger.servingFor('exec-1') => { harness: 'pi', model: 'x' }
	 * @param {string} executionId - Lease execution id.
	 * @returns {Object|null} Serving `{ harness, model }`.
	 ***/
	servingFor(executionId) {
		return this.stageServing.get(executionId) ?? null;
	}

	snapshot() {
		return { ...this.counters };
	}
}

import { RUNNER_PROTOCOL } from "../runnerRegistry.js";
import { runnerApiCompatible } from "./runnerApiCompat.js";

/***
 * MARK: runnerMatches
 * @description Decides whether one Runner registration can take a task with
 *   the given requirements: active status, not paused, fresh heartbeat
 *   (staleness expiry), v1 protocol, runnable flag, harness id, model
 *   offering, tier membership, and disk headroom floor. Returns
 *   `{ ok, reason }` — the
 *   reason code is loud by design (step-6 NO_CAPABLE_RUNNER diagnostics
 *   and the monitor surface distinguish "no runners" from "runners that
 *   cannot take this job"). Alias requirements always miss here; WP-3.2
 *   resolves them centrally first.
 * @example runnerMatches(record, { harness: 'pi', tier: 'T1' }) => { ok: true, reason: 'MATCH' }
 * @param {Object} record - Registry record (`status`, `facts`, `lastSeenAt`, `capabilities`).
 * @param {Object} req - Task requirements from `taskRequirements`.
 * @param {Object} [opts] - `{ now, staleAfterMs, minDiskHeadroomMb }`.
 * @returns {Object} `{ ok, reason }`.
 ***/
export function runnerMatches(record = {}, req = {}, opts = {}) {
	const now = typeof opts.now === "number" ? opts.now : Date.now();
	const staleAfterMs =
		typeof opts.staleAfterMs === "number" && opts.staleAfterMs > 0
			? opts.staleAfterMs
			: 60000;
	const minDisk =
		typeof opts.minDiskHeadroomMb === "number" && opts.minDiskHeadroomMb >= 0
			? opts.minDiskHeadroomMb
			: 100;

	if (record.status !== "active") return { ok: false, reason: "NOT_ACTIVE" };
	if (record.paused === true) return { ok: false, reason: "PAUSED" };
	const seen = Date.parse(record.lastSeenAt || "");
	if (!Number.isFinite(seen) || now - seen > staleAfterMs) {
		return { ok: false, reason: "STALE_HEARTBEAT" };
	}
	const caps = record.capabilities || {};
	if (caps.runnable === false) return { ok: false, reason: "NOT_RUNNABLE" };
	const protocol =
		caps.versions?.protocol || record.facts?.versions?.protocol;
	if (protocol !== RUNNER_PROTOCOL) {
		return { ok: false, reason: "PROTOCOL_SKEW" };
	}
	const runnerApi = caps.versions?.api || record.facts?.versions?.api;
	if (!runnerApiCompatible(runnerApi).ok) {
		return { ok: false, reason: "PROTOCOL_SKEW" };
	}
	// Only the raw string marker (taskRequirements' `{ alias: name }`) is
	// unservable here. A resolved alias object (`{ name, targetIndex }`,
	// stamped by the route after central D3 resolution) carries the
	// concrete harness/model below and matches like any direct requirement.
	if (typeof req.alias === "string" && req.alias) {
		return { ok: false, reason: "ALIAS_UNRESOLVED" };
	}
	if (req.harness) {
		const offered = Array.isArray(caps.harnesses) ? caps.harnesses : [];
		if (!offered.some((h) => h && h.id === req.harness)) {
			return { ok: false, reason: "NO_HARNESS" };
		}
	}
	if (req.model) {
		const models = Array.isArray(caps.models) ? caps.models : [];
		if (!models.includes(req.model)) return { ok: false, reason: "NO_MODEL" };
	}
	if (req.tier) {
		const tiers = Array.isArray(caps.tiers) ? caps.tiers : [];
		if (!tiers.includes(req.tier)) return { ok: false, reason: "TIER_CEILING" };
	}
	if (caps.diskHeadroomMb !== null && caps.diskHeadroomMb !== undefined) {
		if (caps.diskHeadroomMb < minDisk) return { ok: false, reason: "DISK_LOW" };
	}
	return { ok: true, reason: "MATCH" };
}

/***
 * MARK: loadRunnerConfig
 * @description Reads Runner daemon configuration from the environment.
 *   The credential is operator-pasted after human approval (D4): when it
 *   is absent the daemon registers, polls until the join is approved, then
 *   exits with instructions instead of running unapproved. Assignment is
 *   explicit (project + task ids) by default; set KAINBAIN_RUNNER_DISPATCH=1
 *   for the capability-aware dispatch loop (WP-3.1), optionally scoped with
 *   KAINBAIN_RUNNER_PROJECTS.
 * @example loadRunnerConfig({ KAINBAIN_RUNNER_ID: 'r1' }) => { runnerId: 'r1', ... }
 * @param {Object} [env] - Environment mapping (defaults to process.env).
 * @returns {Object} Normalized config.
 ***/
export function loadRunnerConfig(env = process.env) {
	const errors = [];
	const str = (key, fallback = "") => {
		const value = env[key] ?? fallback;
		return typeof value === "string" ? value.trim() : String(value ?? "").trim();
	};

	const backendUrl = str("KAINBAIN_RUNNER_BACKEND", "http://localhost:3100").replace(/\/+$/, "");
	const runnerId = str("KAINBAIN_RUNNER_ID", "");
	// Multi-harness service (one Runner, several harnesses): the csv
	// KAINBAIN_RUNNER_HARNESSES wins when set; otherwise the singular
	// KAINBAIN_RUNNER_HARNESS seeds a 1-element list. The first entry
	// stays the primary harness (single-assignment default, posture).
	const harnessIds = str("KAINBAIN_RUNNER_HARNESSES", "")
		.split(",")
		.map((h) => h.trim())
		.filter(Boolean);
	const singularHarness = str("KAINBAIN_RUNNER_HARNESS", "");
	if (harnessIds.length === 0 && singularHarness) harnessIds.push(singularHarness);
	const harnessId = harnessIds[0] ?? "";
	// Servable model advertisement (capability matching is backend-side, so
	// the list is the operator's claim of what this host can run; the
	// dispatch answer carries the required model per assignment and the
	// daemon serves exactly that). KAINBAIN_RUNNER_MODELS (csv) wins when
	// set; otherwise the singular KAINBAIN_RUNNER_MODEL seeds a 1-element
	// list; empty means unpinned (matches model-less tasks only).
	const model = str("KAINBAIN_RUNNER_MODEL", "");
	const models = str("KAINBAIN_RUNNER_MODELS", "")
		.split(",")
		.map((m) => m.trim())
		.filter(Boolean);
	if (models.length === 0 && model) models.push(model);
	const projectId = str("KAINBAIN_RUNNER_PROJECT_ID", "");
	const taskId = str("KAINBAIN_RUNNER_TASK_ID", "");
	if (!runnerId) errors.push("KAINBAIN_RUNNER_ID is required (stable per host).");
	if (!harnessId) errors.push("KAINBAIN_RUNNER_HARNESS is required (e.g. pi, codex, mock).");
	const dispatch = str("KAINBAIN_RUNNER_DISPATCH", "") === "1";
	if (!dispatch && !projectId) {
		errors.push("KAINBAIN_RUNNER_PROJECT_ID is required (or set KAINBAIN_RUNNER_DISPATCH=1).");
	}
	if (!dispatch && !taskId) {
		errors.push("KAINBAIN_RUNNER_TASK_ID is required (or set KAINBAIN_RUNNER_DISPATCH=1).");
	}

	const heartbeatMs = Number.parseInt(str("KAINBAIN_RUNNER_HEARTBEAT_MS", "15000"), 10);
	const approvalPollMs = Number.parseInt(str("KAINBAIN_RUNNER_APPROVAL_POLL_MS", "5000"), 10);
	const approvalTimeoutMs = Number.parseInt(str("KAINBAIN_RUNNER_APPROVAL_TIMEOUT_MS", "300000"), 10);
	const dispatchPollMs = Number.parseInt(str("KAINBAIN_RUNNER_DISPATCH_POLL_MS", "5000"), 10);
	const dispatchIdleLimit = Number.parseInt(str("KAINBAIN_RUNNER_DISPATCH_IDLE_LIMIT", "3"), 10);

	return {
		backendUrl,
		joinToken: str("KAINBAIN_RUNNER_JOIN_TOKEN", ""),
		credential: str("KAINBAIN_RUNNER_CREDENTIAL", ""),
		runnerId,
		harnessId,
		harnessIds,
		model,
		models,
		tiers: str("KAINBAIN_RUNNER_TIERS", "T0,T1")
			.split(",")
			.map((t) => t.trim())
			.filter(Boolean),
		workRoot: str("KAINBAIN_RUNNER_WORK_ROOT", "runner-work"),
		projectId,
		taskId,
		dispatch,
		projectIds: str("KAINBAIN_RUNNER_PROJECTS", "")
			.split(",")
			.map((p) => p.trim())
			.filter(Boolean),
		dispatchPollMs: Number.isFinite(dispatchPollMs) && dispatchPollMs > 0 ? dispatchPollMs : 5000,
		dispatchIdleLimit:
			Number.isFinite(dispatchIdleLimit) && dispatchIdleLimit >= 0 ? dispatchIdleLimit : 3,
		heartbeatMs: Number.isFinite(heartbeatMs) && heartbeatMs > 0 ? heartbeatMs : 15000,
		approvalPollMs: Number.isFinite(approvalPollMs) && approvalPollMs > 0 ? approvalPollMs : 5000,
		approvalTimeoutMs:
			Number.isFinite(approvalTimeoutMs) && approvalTimeoutMs > 0 ? approvalTimeoutMs : 300000,
		errors,
	};
}
